class Solution { private static final int LARGE=2_000_000_000;private long shortest(int n,int[][] edges,int source,int destination){List<int[]>[] graph=new ArrayList[n];for(int i=0;i<n;i++)graph[i]=new ArrayList<>();for(int[] edge:edges)if(edge[2]>=0){graph[edge[0]].add(new int[]{edge[1],edge[2]});graph[edge[1]].add(new int[]{edge[0],edge[2]});}long[] distance=new long[n];Arrays.fill(distance,Long.MAX_VALUE);distance[source]=0;PriorityQueue<long[]> queue=new PriorityQueue<>(Comparator.comparingLong(state->state[0]));queue.add(new long[]{0,source});while(!queue.isEmpty()){long[] state=queue.poll();long cost=state[0];int node=(int)state[1];if(cost!=distance[node])continue;if(node==destination)return cost;for(int[] next:graph[node]){long candidate=cost+next[1];if(candidate<distance[next[0]]){distance[next[0]]=candidate;queue.add(new long[]{candidate,next[0]});}}}return Long.MAX_VALUE;}public int[][] modifiedGraphEdges(int n,int[][] edges,int source,int destination,int target){long fixed=shortest(n,edges,source,destination);if(fixed<target)return new int[0][0];boolean matched=fixed==target;for(int[] edge:edges)if(edge[2]==-1){if(matched)edge[2]=LARGE;else{edge[2]=1;long distance=shortest(n,edges,source,destination);if(distance<=target){edge[2]+=(int)(target-distance);matched=true;}}}return matched?edges:new int[0][0];} }
